/* Shared charging planner; browser copy is generated by scripts/sync-source-status.js. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports)
    module.exports = factory(require('../pricing/coverage'));
  else root.ChargingPlanner = factory(root.PriceCoverage);
})(typeof globalThis !== 'undefined' ? globalThis : this, function (PriceCoverage) {
  'use strict';
  const { coverageFor } = PriceCoverage;

  const DAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
  const DEFAULTS = Object.freeze({
    minimumSoc: 30,
    minimumDeadline: '07:00',
    usableBatteryKWh: 75,
    chargingEfficiency: 0.92,
    maxChargingPowerKW: 10,
    timezone: 'Europe/Stockholm',
    dailyTargets: {
      mon: { enabled: false, time: '07:00', soc: 80 },
      tue: { enabled: false, time: '07:00', soc: 80 },
      wed: { enabled: false, time: '07:00', soc: 80 },
      thu: { enabled: false, time: '07:00', soc: 80 },
      fri: { enabled: false, time: '07:00', soc: 80 },
      sat: { enabled: false, time: '09:00', soc: 80 },
      sun: { enabled: false, time: '09:00', soc: 80 },
    },
  });

  function validTime(time) {
    if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) throw new Error(`Invalid time: ${time}`);
    return time;
  }
  function validateConfig(config) {
    if (
      !config ||
      typeof config !== 'object' ||
      Array.isArray(config) ||
      !config.dailyTargets ||
      typeof config.dailyTargets !== 'object'
    )
      throw new Error('Invalid charging configuration');
    if (typeof config.timezone !== 'string' || config.timezone.length > 100)
      throw new Error('Invalid timezone');
    try {
      new Intl.DateTimeFormat('en-GB', { timeZone: config.timezone }).format(new Date(0));
    } catch {
      throw new Error('Invalid timezone');
    }
    if (!Number.isFinite(config.minimumSoc) || config.minimumSoc < 0 || config.minimumSoc > 100)
      throw new Error('Invalid minimum SoC');
    validTime(config.minimumDeadline);
    if (
      !Number.isFinite(config.usableBatteryKWh) ||
      config.usableBatteryKWh > 1000 ||
      !(config.usableBatteryKWh > 0) ||
      !(config.chargingEfficiency > 0 && config.chargingEfficiency <= 1) ||
      !Number.isFinite(config.maxChargingPowerKW) ||
      config.maxChargingPowerKW > 350 ||
      !(config.maxChargingPowerKW > 0)
    )
      throw new Error('Invalid charging parameters');
    for (const day of DAYS) {
      const target = config.dailyTargets[day];
      if (
        !target ||
        typeof target.enabled !== 'boolean' ||
        !Number.isFinite(target.soc) ||
        target.soc < 0 ||
        target.soc > 100
      )
        throw new Error(`Invalid target for ${day}`);
      validTime(target.time);
    }
    return config;
  }
  // Resolve each local calendar deadline once. Spring gaps move to the first
  // valid minute after the requested clock time; autumn repeats use the first occurrence.
  function upcomingDeadlines(config, now, horizonHours = 48) {
    validateConfig(config);
    if (
      typeof now?.getTime !== 'function' ||
      !Number.isFinite(now.getTime()) ||
      !Number.isFinite(horizonHours) ||
      horizonHours <= 0 ||
      horizonHours > 48
    )
      throw new Error('Invalid planning horizon');
    const formatter = new Intl.DateTimeFormat('en-GB', {
      timeZone: config.timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hourCycle: 'h23',
      weekday: 'short',
    });
    const byDate = new Map(),
      start = Math.floor(now.getTime() / 86400000) * 86400000 - 86400000,
      end = now.getTime() + horizonHours * 3600000;
    for (let ms = start; ms <= end + 86400000; ms += 60000) {
      const p = Object.fromEntries(
        formatter.formatToParts(new Date(ms)).map((x) => [x.type, x.value]),
      );
      const date = `${p.year}-${p.month}-${p.day}`,
        time = `${p.hour}:${p.minute}`;
      const daily = config.dailyTargets[p.weekday.toLowerCase()];
      const targets = [
        { time: config.minimumDeadline, soc: config.minimumSoc, type: 'minimum' },
        ...(daily.enabled ? [{ ...daily, type: 'daily' }] : []),
      ];
      for (const target of targets) {
        if (time < target.time) continue;
        const key = date + target.type,
          old = byDate.get(key);
        if (!old || time < old.resolvedTime)
          byDate.set(key, {
            at: new Date(ms),
            soc: target.soc,
            type: target.type,
            requestedTime: target.time,
            resolvedTime: time,
            matches: time === target.time ? 1 : 0,
          });
        else if (time === target.time && time === old.resolvedTime) old.matches++;
      }
    }
    return [...byDate.values()]
      .filter((d) => d.at.getTime() >= now.getTime() && d.at.getTime() <= end)
      .map(({ matches, ...d }) => ({
        ...d,
        adjustment:
          d.resolvedTime !== d.requestedTime
            ? 'dst-gap-forward'
            : matches > 1
              ? 'dst-first-occurrence'
              : null,
      }))
      .sort((a, b) => a.at - b.at || a.soc - b.soc);
  }

  /**
   * Read-only, price-driven charging plan. Each slot: {start, end, price} in ISO/Date.
   * Splits work across cheapest available slots, subject to all SoC deadlines.
   * Assumes fixed charging power and constant efficiency; no battery/grid dispatch.
   */
  function planCharging({ now = new Date(), currentSoc, config, prices, maxPowerKW }) {
    validateConfig(config);
    if (!Number.isFinite(currentSoc) || currentSoc < 0 || currentSoc > 100)
      throw new Error('Invalid vehicle SoC');
    if (maxPowerKW !== undefined && (!Number.isFinite(maxPowerKW) || maxPowerKW <= 0))
      throw new Error('Invalid available charging power');
    const power = Math.min(config.maxChargingPowerKW, maxPowerKW ?? config.maxChargingPowerKW);
    if (!Number.isFinite(power) || !(power > 0))
      throw new Error('Invalid available charging power');
    const deadlines = upcomingDeadlines(config, now);
    if (!Array.isArray(prices) || prices.length > 512) throw new Error('Invalid price slots');
    if (
      prices.some(
        (p) =>
          p?.start === null || p?.start === undefined || p?.end === null || p?.end === undefined,
      )
    )
      throw new Error('Invalid price slot');
    const slots = prices
      .map((p, index) => ({
        index,
        start: new Date(p.start).getTime(),
        end: new Date(p.end).getTime(),
        price: p.price,
      }))
      .map((s) => {
        if (
          !Number.isFinite(s.start) ||
          !Number.isFinite(s.end) ||
          !Number.isFinite(s.price) ||
          s.end <= s.start
        )
          throw new Error('Invalid price slot');
        return s;
      })
      .filter((s) => s.end > now.getTime() && s.start < now.getTime() + 48 * 3600000)
      .map((s) => ({ ...s, start: Math.max(s.start, now.getTime()), allocatedKWh: 0 }))
      .filter((s) => s.end > s.start);
    for (const slot of slots) {
      if (!Number.isFinite(slot.price) || !(slot.end > slot.start))
        throw new Error('Invalid price slot');
    }
    slots.sort((a, b) => a.start - b.start);
    for (let i = 1; i < slots.length; i++) {
      if (slots[i].start < slots[i - 1].end) throw new Error('Overlapping price slots');
    }
    const priceCoverage = deadlines.map((deadline) => ({
      at: deadline.at.toISOString(),
      type: deadline.type,
      ...coverageFor(slots, now.getTime(), deadline.at.getTime()),
    }));
    const unmet = [];
    let committedBatteryKWh = 0;
    const batteryKWh = config.usableBatteryKWh;
    for (const deadline of deadlines) {
      const requiredBatteryKWh = Math.max(0, ((deadline.soc - currentSoc) / 100) * batteryKWh);
      let remainingInputKWh = Math.max(
        0,
        (requiredBatteryKWh - committedBatteryKWh) / config.chargingEfficiency,
      );
      const candidates = slots
        .filter((s) => s.start < deadline.at.getTime())
        .sort((a, b) => a.price - b.price || a.start - b.start);
      for (const slot of candidates) {
        const durationHours = (Math.min(slot.end, deadline.at.getTime()) - slot.start) / 3600000;
        const freeKWh = Math.max(0, durationHours * power - slot.allocatedKWh);
        const allocated = Math.min(remainingInputKWh, freeKWh);
        slot.allocatedKWh += allocated;
        remainingInputKWh -= allocated;
        if (remainingInputKWh < 1e-8) break;
      }
      const delivered = requiredBatteryKWh - remainingInputKWh * config.chargingEfficiency;
      committedBatteryKWh = Math.max(committedBatteryKWh, delivered);
      if (remainingInputKWh > 1e-6)
        unmet.push({
          type: deadline.type,
          at: deadline.at.toISOString(),
          missingBatteryKWh: Number((remainingInputKWh * config.chargingEfficiency).toFixed(3)),
        });
    }
    return {
      createdAt: now.toISOString(),
      currentSoc,
      deadlines: deadlines.map((d) => ({ ...d, at: d.at.toISOString() })),
      slots: slots
        .filter((s) => s.allocatedKWh > 1e-8)
        .map((s) => ({
          start: new Date(s.start).toISOString(),
          end: new Date(s.end).toISOString(),
          inputKWh: Number(s.allocatedKWh.toFixed(4)),
          price: s.price,
        })),
      unmet,
      priceCoverage,
      estimatedCost: Number(slots.reduce((sum, s) => sum + s.allocatedKWh * s.price, 0).toFixed(2)),
      status: unmet.length
        ? 'unreachable'
        : deadlines.some((d, i) => d.soc > currentSoc && !priceCoverage[i].complete)
          ? 'partial-prices'
          : 'planned',
    };
  }
  return { DEFAULTS, DAYS, validateConfig, upcomingDeadlines, planCharging };
});
